CREATE OR REPLACE FUNCTION public.crm_can_access(p_owner uuid, p_unit uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR (EXISTS (SELECT 1 FROM public.user_units u WHERE u.user_id=auth.uid() AND u.unit_id=p_unit) AND (public.has_role(auth.uid(),'gerente_unidade') OR (public.has_role(auth.uid(),'vendedor') AND p_owner=auth.uid())))) $$;
REVOKE ALL ON FUNCTION public.crm_can_access(uuid,uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.crm_can_access(uuid,uuid) TO authenticated,service_role;
CREATE TABLE public.crm_companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,document text,phone text,email text,segment text,address text,source text NOT NULL DEFAULT 'manual',interest text NOT NULL DEFAULT 'coffee_break' CHECK(interest IN ('coffee_break','evento_corporativo','encomenda')),status text NOT NULL DEFAULT 'novo' CHECK(status IN ('novo','em_contato','qualificado','descartado')),do_not_contact boolean NOT NULL DEFAULT false,notes text,unit_id uuid NOT NULL REFERENCES public.units(id),owner_id uuid NOT NULL DEFAULT auth.uid(),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.crm_companies TO authenticated;
GRANT ALL ON public.crm_companies TO service_role;
ALTER TABLE public.crm_companies ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_companies_read ON public.crm_companies FOR SELECT TO authenticated USING(public.crm_can_access(owner_id,unit_id));
CREATE POLICY crm_companies_insert ON public.crm_companies FOR INSERT TO authenticated WITH CHECK(public.crm_can_access(owner_id,unit_id) AND (owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')));
CREATE POLICY crm_companies_update ON public.crm_companies FOR UPDATE TO authenticated USING(public.crm_can_access(owner_id,unit_id)) WITH CHECK(public.crm_can_access(owner_id,unit_id));
CREATE UNIQUE INDEX crm_companies_document_unique ON public.crm_companies(document) WHERE document IS NOT NULL;
CREATE INDEX crm_companies_access_idx ON public.crm_companies(unit_id,owner_id);
CREATE TRIGGER crm_companies_updated BEFORE UPDATE ON public.crm_companies FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();
CREATE TABLE public.crm_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.crm_companies(id),name text NOT NULL,position text,phone text,email text,source text NOT NULL DEFAULT 'manual',confirmed boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.crm_contacts TO authenticated;
GRANT ALL ON public.crm_contacts TO service_role;
ALTER TABLE public.crm_contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_contacts_read ON public.crm_contacts FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id AND public.crm_can_access(c.owner_id,c.unit_id)));
CREATE POLICY crm_contacts_insert ON public.crm_contacts FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id AND public.crm_can_access(c.owner_id,c.unit_id)));
CREATE POLICY crm_contacts_update ON public.crm_contacts FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id AND public.crm_can_access(c.owner_id,c.unit_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id AND public.crm_can_access(c.owner_id,c.unit_id)));
CREATE INDEX crm_contacts_company_idx ON public.crm_contacts(company_id);
CREATE TRIGGER crm_contacts_updated BEFORE UPDATE ON public.crm_contacts FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();
CREATE TABLE public.crm_opportunities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.crm_companies(id),title text NOT NULL,stage text NOT NULL DEFAULT 'qualificacao' CHECK(stage IN ('qualificacao','briefing','proposta','negociacao','ganha','perdida')),estimated_value numeric NOT NULL DEFAULT 0 CHECK(estimated_value>=0),sale_type text NOT NULL DEFAULT 'coffee_break' CHECK(sale_type IN ('coffee_break','evento_corporativo','encomenda')),event_date date,event_time text,attendees integer CHECK(attendees>0),delivery_mode text NOT NULL DEFAULT 'entrega' CHECK(delivery_mode IN ('entrega','retirada')),address text,requirements text,requested_items text,loss_reason text,closed_at timestamptz,unit_id uuid NOT NULL REFERENCES public.units(id),production_unit_id uuid REFERENCES public.units(id),owner_id uuid NOT NULL DEFAULT auth.uid(),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(stage<>'perdida' OR nullif(trim(loss_reason),'') IS NOT NULL));
GRANT SELECT,INSERT,UPDATE ON public.crm_opportunities TO authenticated;
GRANT ALL ON public.crm_opportunities TO service_role;
ALTER TABLE public.crm_opportunities ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_opportunities_read ON public.crm_opportunities FOR SELECT TO authenticated USING(public.crm_can_access(owner_id,unit_id) AND EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id));
CREATE POLICY crm_opportunities_insert ON public.crm_opportunities FOR INSERT TO authenticated WITH CHECK(public.crm_can_access(owner_id,unit_id) AND (owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')) AND EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id));
CREATE POLICY crm_opportunities_update ON public.crm_opportunities FOR UPDATE TO authenticated USING(public.crm_can_access(owner_id,unit_id) AND EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id)) WITH CHECK(public.crm_can_access(owner_id,unit_id) AND EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id));
CREATE INDEX crm_opportunities_access_idx ON public.crm_opportunities(unit_id,owner_id,stage);
CREATE TRIGGER crm_opportunities_updated BEFORE UPDATE ON public.crm_opportunities FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();
CREATE TABLE public.crm_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.crm_companies(id),opportunity_id uuid REFERENCES public.crm_opportunities(id),title text NOT NULL,kind text NOT NULL DEFAULT 'tarefa' CHECK(kind IN ('tarefa','ligacao','reuniao','degustacao','mensagem')),due_date date,completed boolean NOT NULL DEFAULT false,notes text,unit_id uuid NOT NULL REFERENCES public.units(id),owner_id uuid NOT NULL DEFAULT auth.uid(),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.crm_activities TO authenticated;
GRANT ALL ON public.crm_activities TO service_role;
ALTER TABLE public.crm_activities ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_activities_read ON public.crm_activities FOR SELECT TO authenticated USING(public.crm_can_access(owner_id,unit_id) AND EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id));
CREATE POLICY crm_activities_insert ON public.crm_activities FOR INSERT TO authenticated WITH CHECK(public.crm_can_access(owner_id,unit_id) AND (owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')) AND EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id) AND (opportunity_id IS NULL OR EXISTS(SELECT 1 FROM public.crm_opportunities o WHERE o.id=opportunity_id AND o.company_id=crm_activities.company_id)));
CREATE POLICY crm_activities_update ON public.crm_activities FOR UPDATE TO authenticated USING(public.crm_can_access(owner_id,unit_id) AND EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id)) WITH CHECK(public.crm_can_access(owner_id,unit_id) AND EXISTS(SELECT 1 FROM public.crm_companies c WHERE c.id=company_id) AND (opportunity_id IS NULL OR EXISTS(SELECT 1 FROM public.crm_opportunities o WHERE o.id=opportunity_id AND o.company_id=crm_activities.company_id)));
CREATE INDEX crm_activities_agenda_idx ON public.crm_activities(unit_id,owner_id,due_date);
CREATE TRIGGER crm_activities_updated BEFORE UPDATE ON public.crm_activities FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();